        let mergedResult:
            | { timeline: MatrixEvent[]; ourEventsIndexes: number[]; roomId: string; roomName: string }
            | undefined;

        const renderMergedResult = () => {
            if (!mergedResult) return;

            const { timeline, ourEventsIndexes, roomId, roomName } = mergedResult;
            const firstMatch = timeline[ourEventsIndexes[0]];

            if (scope === SearchScope.All && roomId !== lastRoomId) {
                ret.push(
                    <li key={firstMatch.getId() + "-room"}>
                        <h2>
                            {_t("Room")}: {roomName}
                        </h2>
                    </li>,
                );
                lastRoomId = roomId;
            }

            ret.push(
