                    key={firstMatch.getId()}
                    timeline={timeline}
                    ourEventsIndexes={ourEventsIndexes}
                    searchHighlights={highlights}
                    permalinkCreator={permalinkCreator}
                    onHeightChanged={onHeightChanged}
                />,
            );
            mergedResult = undefined;
        };

        for (let i = (results?.results?.length || 0) - 1; i >= 0; i--) {
            const result = results.results[i];

            const mxEv = result.context.getEvent();
            const roomId = mxEv.getRoomId();
            const room = client.getRoom(roomId);
            if (!room) {
                // if we do not have the room in js-sdk stores then hide it as we cannot easily show it
                // As per the spec, an all rooms search can create this condition,
                // it happens with Seshat but not Synapse.
                // It will make the result count not match the displayed count.
                logger.log("Hiding search result from an unknown room", roomId);
                renderMergedResult();
                continue;
            }

            if (!haveRendererForEvent(mxEv, roomContext.showHiddenEvents)) {
                // XXX: can this ever happen? It will make the result count
                // not match the displayed count.
                renderMergedResult();
                continue;
            }

            const timeline = result.context.getTimeline();
            const nextOurEventIndex = result.context.getOurEventIndex();
            if (nextOurEventIndex < 0 || nextOurEventIndex >= timeline.length) {
                renderMergedResult();
                continue;
            }

            const firstEvent = timeline[0];
            const lastMergedEvent = mergedResult?.timeline[mergedResult.timeline.length - 1];
            const overlaps =
                mergedResult &&
                mergedResult.ourEventsIndexes.length > 0 &&
                firstEvent &&
                lastMergedEvent?.getId() === firstEvent.getId();

            if (overlaps) {
                const offset = mergedResult.timeline.length;
                mergedResult.ourEventsIndexes.push(offset + (nextOurEventIndex - 1));
                mergedResult.timeline.push(...timeline.slice(1));
            } else {
                renderMergedResult();
                mergedResult = {
                    timeline: [...timeline],
                    ourEventsIndexes: [nextOurEventIndex],
                    roomId,
                    roomName: room.name,
                };
            }
        }

        renderMergedResult();

        return (
            <ScrollPanel
                ref={ref}
                className={"mx_RoomView_searchResultsPanel " + className}
                onFillRequest={onSearchResultsFillRequest}
                resizeNotifier={resizeNotifier}
            >
                <li className="mx_RoomView_scrollheader" />
                {ret}
            </ScrollPanel>
        );
    },
);

import RoomContext, { TimelineRenderingType } from "../../../contexts/RoomContext";
import SettingsStore from "../../../settings/SettingsStore";
import { RoomPermalinkCreator } from "../../../utils/permalinks/Permalinks";
import DateSeparator from "../messages/DateSeparator";
import EventTile from "./EventTile";
import { shouldFormContinuation } from "../../structures/MessagePanel";
import { wantsDateSeparator } from "../../../DateUtils";
import LegacyCallEventGrouper, { buildLegacyCallEventGroupers } from "../../structures/LegacyCallEventGrouper";
import { haveRendererForEvent } from "../../../events/EventTileFactory";

interface IProps {
    // The merged context events to render in chronological order.
    timeline: MatrixEvent[];
    // Indices into timeline for events matching the search query.
    ourEventsIndexes: number[];
    searchHighlights?: string[];
    onHeightChanged?: () => void;
    permalinkCreator?: RoomPermalinkCreator;
}

export default class SearchResultTile extends React.Component<IProps> {
    public static contextType = RoomContext;
    public context!: React.ContextType<typeof RoomContext>;

    // A map of <callId, LegacyCallEventGrouper>
    private callEventGroupers = new Map<string, LegacyCallEventGrouper>();

    public constructor(props, context) {
        super(props, context);

        this.buildLegacyCallEventGroupers(this.props.timeline);
    }

    public componentDidUpdate(prevProps: IProps): void {
        if (prevProps.timeline !== this.props.timeline) {
            this.buildLegacyCallEventGroupers(this.props.timeline);
        }
    }

    private buildLegacyCallEventGroupers(events?: MatrixEvent[]): void {
        this.callEventGroupers = buildLegacyCallEventGroupers(this.callEventGroupers, events);
    }

    public render() {
        const { timeline, ourEventsIndexes } = this.props;
        const resultEvent = timeline[ourEventsIndexes[0]];
        const eventIds = [...new Set(ourEventsIndexes.map((index) => timeline[index].getId()))];

        const ts1 = resultEvent.getTs();
        const ret = [<DateSeparator key={ts1 + "-search"} roomId={resultEvent.getRoomId()} ts={ts1} />];
        const layout = SettingsStore.getValue("layout");
        const isTwelveHour = SettingsStore.getValue("showTwelveHourTimestamps");
        const alwaysShowTimestamps = SettingsStore.getValue("alwaysShowTimestamps");
        const threadsEnabled = SettingsStore.getValue("feature_threadstable");

        const matchedEventIndexes = new Set(ourEventsIndexes);
        for (let j = 0; j < timeline.length; j++) {
            const mxEv = timeline[j];
            let highlights;
            const contextual = !matchedEventIndexes.has(j);
            if (!contextual) {
                highlights = this.props.searchHighlights;
            }

            if (haveRendererForEvent(mxEv, this.context?.showHiddenEvents)) {
                // do we need a date separator since the last event?
                const prevEv = timeline[j - 1];
                // is this a continuation of the previous message?
                const continuation =
                    prevEv &&
                    !wantsDateSeparator(prevEv.getDate(), mxEv.getDate()) &&
                    shouldFormContinuation(
                        prevEv,
                        mxEv,
                        this.context?.showHiddenEvents,
                        threadsEnabled,
                        TimelineRenderingType.Search,
                    );

                let lastInSection = true;
                const nextEv = timeline[j + 1];
                if (nextEv) {
                    const willWantDateSeparator = wantsDateSeparator(mxEv.getDate(), nextEv.getDate());
                    lastInSection =
                        willWantDateSeparator ||
                        mxEv.getSender() !== nextEv.getSender() ||
                        !shouldFormContinuation(
                            mxEv,
                            nextEv,
                            this.context?.showHiddenEvents,
                            threadsEnabled,
                            TimelineRenderingType.Search,
                        );
                }

                ret.push(
                    <EventTile
                        key={`${eventId}+${j}`}
                        mxEvent={mxEv}
                        layout={layout}
                        contextual={contextual}
                        highlights={highlights}
                        permalinkCreator={this.props.permalinkCreator}
                        highlightLink={
                            contextual ? undefined : `#/room/${mxEv.getRoomId()}/${mxEv.getId()}`
                        }
                        onHeightChanged={this.props.onHeightChanged}
                        isTwelveHour={isTwelveHour}
                        alwaysShowTimestamps={alwaysShowTimestamps}
                        lastInSection={lastInSection}
                        continuation={continuation}
                        callEventGrouper={this.callEventGroupers.get(mxEv.getContent().call_id)}
                    />,
                );
            }
        }

        return (
            <li data-scroll-tokens={eventIds.join(",")}>
                <ol>{ret}</ol>
            </li>
        );
    }
}

